{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or slightly positive (≥0.00) and historical price mean reversion is observed.",
    "Reduce forecast overshoots following sharp price spikes (e.g., >70.00) by 5–10% to avoid overreaction.",
    "Apply a lag correction: if true outcome is lower than forecast by >3% for 3+ consecutive days, reduce next forecast by 1–2%.",
    "Increase forecast sensitivity to sentiment shifts: if sentiment turns negative (≤-0.25), reduce forecast by 2–5% for the next 3 days.",
    "Apply mean reversion bias: if forecast is >10% above recent 7-day average, reduce by 1–3% per day until convergence.",
    "Avoid over-optimism in early forecast windows (e.g., first 5 days of 30d forecast) — cap forecast at 10% below recent 18-day high."
  ]
}
